view.template:
{% load view_tags %}
{% get_set 'project/partner/id' as partners %}
{% get_value 'project/title' as title %}
{% get_value 'project/schedule/project_end' as release_date %}
{% get_values 'smp/software-pid' as software_pids %}
{% get_values 'smp/software-license' as software_licenses %}
<pre>
cff-version: 1.2.0
message: "If you use this software, please cite it as below."
title: {% if ' ' in title.value %}"{{ title.value }}"{% else %}{{  title.value}}{% endif %}
type: software
{% if partners|length %}authors:{% for p in partners %} {% with p_set_index_str=p.set_index|stringformat:"s" %} {% get_set_value p 'project/partner/type' as p_type %} {% get_set_value p 'project/partner/family-name' as p_family_name %} {% get_set_value p 'project/partner/given-name' as p_given_name %} {% get_set_value p 'project/partner/name' as p_name %} {% get_set_value p 'project/partner/orcid' as p_orcid %} {% get_set_value p 'project/partner/website' as p_website %} {% get_values 'project/partner/affiliation' p_set_index_str as p_affiliations %}
    {% if p_type.option_uri == 'https://rdmo.mpdl.mpg.de/terms/options/partner-types/person' %}- family-names: {% if ' ' in p_family_name.value or p_family_name.value == '' %}"{{ p_family_name.value }}"{% else %}{{ p_family_name.value }}{% endif %}<br>      given-names: {% if ' ' in p_given_name.value or p_given_name.value == '' %}"{{ p_given_name.value }}"{% else %}{{ p_given_name.value }}{% endif %}{% if p_orcid.value %}<br>      orcid: {{ p_orcid.value }}{% endif %}{% elif p_type.option_uri == 'https://rdmo.mpdl.mpg.de/terms/options/partner-types/entity' %}- name: {% if ' ' in p_name.value or p_name.value == '' %}"{{ p_name.value }}"{% else %}{{ p_name.value }}{% endif %}{% if p_website.value %}<br>      website: {{ p_website.value }}{% endif %}{% endif %}{% if p_affiliations|length %}<br>      affiliation: "{% for a in p_affiliations %}{{ a.value }}{% if not forloop.last %} & {% endif %}{% endfor %}"{% endif %}{% endwith %}{% endfor %}
{% endif %}{% if software_pids|length == 1 %}{% if software_pids.0.option_text == 'DOI' or software_pids.0.option_text == 'URL' %}{{ software_pids.0.option_text|lower }}: {% if ' ' in software_pids.0.text or software_pids.0.text == '' %}"{{ software_pids.0.text }}"{% else %}{{ software_pids.0.text }}{% endif %}<br>{% else %}identifiers: {% for sp in software_pids %}
    - type: {% if sp.option_text == 'Software Heritage Identifier' %}swh{% else %}{{ sp.option_text|lower }}{% endif %}
      value: {% if ' ' in sp.text or sp.text == '' %}"{{ sp.text }}"{% else %}{{ sp.text }}{% endif %}{% endfor %}{% endif %}{% elif software_pids|length > 1 %}identifiers: {% for sp in software_pids %}
    - type: {% if sp.option_text == 'Software Heritage Identifier' %}swh{% else %}{{ sp.option_text|lower }}{% endif %}
      value: {% if ' ' in sp.text or sp.text == '' %}"{{ sp.text }}"{% else %}{{ sp.text }}{% endif %}{% endfor %}
{% endif %}{% if software_licenses|length == 1 %}license: {% if software_licenses.0.text %}{% if ' ' in software_licenses.0.text or software_licenses.0.text == '' %}"{{ software_licenses.0.text }}"{% else %}{{ software_licenses.0.text }}{% endif %}{% else %}{{ software_licenses.0.option_text }}{% endif %}
{% elif software_licenses|length > 1 %}license: {% for sl in software_licenses %}{% if forloop.first %}<br>{% endif %}    {% if sl.text %}{% if ' ' in sl.text or sl.text == '' %}- "{{ sl.text }}"{% else %}- {{ sl.text }}{% endif %}{% else %}- {{ sl.option_text }}{% endif %}
{% endfor %}{% endif %}{% if release_date %}date-released: {{ release_date.value|date:"Y-m-d" }}{% endif %}
</pre>
